 * @param {{ lines: Array<{ qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }}
 * @returns {{ subtotal: number, discount: number, vat: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = roundCents(invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0));
  const discount = roundCents(invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0));
  const vat = roundCents(invoice.lines.reduce((sum, line) => sum + lineVAT(line), 0));
  const total = Math.max(0, subtotal - discount + vat);
  return {
    subtotal,
    discount,
    vat,
    total,
  };
}

/**
 * Add or update a line on an invoice.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array<any> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} lineInput
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, lineInput) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const { sku, qty } = lineInput;
  if (!isValidQty(qty)) return fail('QTY_INVALID');

  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;
  const discount = 'discountPercent' in lineInput ? lineInput.discountPercent : TIER_DISCOUNTS[customer.tier];
  if (!isValidDiscount(discount)) return fail('DISCOUNT_INVALID');

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

